CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

CREATE TABLE "Categorias" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Codigo" character varying(25) NOT NULL,
    "Descricao" character varying(50) NOT NULL,
    "Status" integer NOT NULL,
    CONSTRAINT "PK_Categorias" PRIMARY KEY ("Id"),
    CONSTRAINT "AK_Categorias_Codigo" UNIQUE ("Codigo")
);

CREATE TABLE "Clientes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Codigo" character varying(25) NOT NULL,
    "Nome" character varying(50) NOT NULL,
    "CPF" character varying(11) NULL,
    "CNPJ" character varying(14) NULL,
    "Status" integer NOT NULL,
    "Endereco_Logradouro" character varying(100) NULL,
    "Endereco_Numero" character varying(10) NULL,
    "Endereco_Cidade" character varying(50) NULL,
    "Endereco_UF" character varying(2) NULL,
    "Endereco_CEP" character varying(9) NULL,
    "Email" character varying(50) NOT NULL,
    "Telefone" character varying(15) NOT NULL,
    CONSTRAINT "PK_Clientes" PRIMARY KEY ("Id")
);

CREATE TABLE "Fornecedores" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Codigo" character varying(25) NOT NULL,
    "Nome" character varying(100) NOT NULL,
    "CNPJ" character varying(14) NOT NULL,
    "Email" character varying(100) NOT NULL,
    "Telefone" character varying(20) NOT NULL,
    "Endereco_Logradouro" character varying(100) NULL,
    "Endereco_Numero" character varying(10) NULL,
    "Endereco_Cidade" character varying(50) NULL,
    "Endereco_UF" character varying(2) NULL,
    "Endereco_CEP" character varying(9) NULL,
    CONSTRAINT "PK_Fornecedores" PRIMARY KEY ("Id")
);

CREATE TABLE "Produtos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Codigo" character varying(25) NOT NULL,
    "Descricao" character varying(50) NOT NULL,
    CONSTRAINT "PK_Produtos" PRIMARY KEY ("Id")
);

CREATE TABLE "Vendas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "DataVenda" timestamp without time zone NOT NULL,
    "Removido" boolean NOT NULL,
    "RemovidoEm" timestamp without time zone NULL,
    "ClienteId" integer NOT NULL,
    "ClienteCodigo" character varying(25) NOT NULL,
    CONSTRAINT "PK_Vendas" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Vendas_Clientes_ClienteId" FOREIGN KEY ("ClienteId") REFERENCES "Clientes" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Entradas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FornecedorId" integer NOT NULL,
    "FornecedorCodigo" character varying(25) NOT NULL,
    "DataEntrada" timestamp without time zone NOT NULL,
    "Observacao" character varying(500) NULL,
    CONSTRAINT "PK_Entradas" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Entradas_Fornecedores_FornecedorId" FOREIGN KEY ("FornecedorId") REFERENCES "Fornecedores" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Estoques" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ProdutoId" integer NOT NULL,
    "Quantidade" integer NOT NULL,
    "DataUltimaAtualizacao" timestamp without time zone NOT NULL,
    CONSTRAINT "PK_Estoques" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Estoques_Produtos_ProdutoId" FOREIGN KEY ("ProdutoId") REFERENCES "Produtos" ("Id") ON DELETE CASCADE
);

CREATE TABLE "ProdutoCategorias" (
    "ProdutoId" integer NOT NULL,
    "CategoriaId" integer NOT NULL,
    "ProdutoCodigo" character varying(25) NOT NULL,
    "CategoriaCodigo" character varying(25) NOT NULL,
    CONSTRAINT "PK_ProdutoCategorias" PRIMARY KEY ("ProdutoId", "CategoriaId"),
    CONSTRAINT "FK_ProdutoCategorias_Categorias_CategoriaId" FOREIGN KEY ("CategoriaId") REFERENCES "Categorias" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_ProdutoCategorias_Produtos_ProdutoId" FOREIGN KEY ("ProdutoId") REFERENCES "Produtos" ("Id") ON DELETE CASCADE
);

CREATE TABLE "ProdutoFornecedor" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ProdutoId" integer NOT NULL,
    "ProdutoCodigo" character varying(25) NOT NULL,
    "FornecedorId" integer NOT NULL,
    "FornecedorCodigo" character varying(25) NOT NULL,
    CONSTRAINT "PK_ProdutoFornecedor" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ProdutoFornecedor_Fornecedores_FornecedorId" FOREIGN KEY ("FornecedorId") REFERENCES "Fornecedores" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_ProdutoFornecedor_Produtos_ProdutoId" FOREIGN KEY ("ProdutoId") REFERENCES "Produtos" ("Id") ON DELETE CASCADE
);

CREATE TABLE "ItensVenda" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "VendaId" integer NOT NULL,
    "ProdutoId" integer NOT NULL,
    "ProdutoCodigo" character varying(25) NOT NULL,
    "Quantidade" integer NOT NULL,
    "PrecoVenda" numeric(18,2) NOT NULL,
    CONSTRAINT "PK_ItensVenda" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ItensVenda_Produtos_ProdutoId" FOREIGN KEY ("ProdutoId") REFERENCES "Produtos" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ItensVenda_Vendas_VendaId" FOREIGN KEY ("VendaId") REFERENCES "Vendas" ("Id") ON DELETE CASCADE
);

CREATE TABLE "ItensEntrada" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "EntradaId" integer NOT NULL,
    "ProdutoId" integer NOT NULL,
    "ProdutoCodigo" character varying(25) NOT NULL,
    "Quantidade" integer NOT NULL,
    "PrecoCusto" numeric(18,2) NOT NULL,
    CONSTRAINT "PK_ItensEntrada" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ItensEntrada_Entradas_EntradaId" FOREIGN KEY ("EntradaId") REFERENCES "Entradas" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_ItensEntrada_Produtos_ProdutoId" FOREIGN KEY ("ProdutoId") REFERENCES "Produtos" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "MovimentacoesEstoque" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "EstoqueId" integer NOT NULL,
    "TipoMovimentacao" integer NOT NULL,
    "Quantidade" integer NOT NULL,
    "DataMovimentacao" timestamp without time zone NOT NULL,
    "Observacao" character varying(200) NULL,
    "Origem" character varying(100) NULL,
    "TransacaoId" integer NULL,
    CONSTRAINT "PK_MovimentacoesEstoque" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_MovimentacoesEstoque_Estoques_EstoqueId" FOREIGN KEY ("EstoqueId") REFERENCES "Estoques" ("Id") ON DELETE CASCADE
);

CREATE INDEX "IX_Entradas_FornecedorId" ON "Entradas" ("FornecedorId");

CREATE UNIQUE INDEX "IX_Estoques_ProdutoId" ON "Estoques" ("ProdutoId");

CREATE UNIQUE INDEX "IX_Fornecedores_Codigo" ON "Fornecedores" ("Codigo");

CREATE INDEX "IX_ItensEntrada_EntradaId" ON "ItensEntrada" ("EntradaId");

CREATE INDEX "IX_ItensEntrada_ProdutoId" ON "ItensEntrada" ("ProdutoId");

CREATE INDEX "IX_ItensVenda_ProdutoId" ON "ItensVenda" ("ProdutoId");

CREATE INDEX "IX_ItensVenda_VendaId" ON "ItensVenda" ("VendaId");

CREATE INDEX "IX_MovimentacoesEstoque_EstoqueId" ON "MovimentacoesEstoque" ("EstoqueId");

CREATE INDEX "IX_ProdutoCategorias_CategoriaId" ON "ProdutoCategorias" ("CategoriaId");

CREATE INDEX "IX_ProdutoFornecedor_FornecedorId" ON "ProdutoFornecedor" ("FornecedorId");

CREATE INDEX "IX_ProdutoFornecedor_ProdutoId" ON "ProdutoFornecedor" ("ProdutoId");

CREATE INDEX "IX_Vendas_ClienteId" ON "Vendas" ("ClienteId");

